try:
    import toml
except ImportError:  # minimal fallback writer for flat integer tables
    class _MiniToml:
        @staticmethod
        def dumps(d):
            return "".join(f"{k} = {int(v)}\n" for k, v in d.items())

        def dump(self, d, f):
            f.write(self.dumps(d))

    toml = _MiniToml()

